from decimal import Decimal as D, ROUND_HALF_UP
def r2(x): return x.quantize(D("0.01"), rounding=ROUND_HALF_UP)
def armar(lineas, tributos=()):
    iva = {}
    neto = D(0)
    for base, alic in lineas:
        base = D(base); neto += base
        iva[alic] = iva.get(alic, D(0)) + base
    imp_iva = sum((r2(b * D(a) / 100) for a, b in iva.items()), D(0))
    imp_trib = sum((r2(D(b) * D(a) / 100) for b, a in tributos), D(0))
    return {"ImpNeto": neto, "ImpIVA": imp_iva, "ImpTrib": imp_trib, "ImpTotal": neto + imp_iva + imp_trib}
# El ejemplo del manual de ARCA: 100 al 21 %, 50 al 10,5 % y un tributo de 150 al 5,2 %
print(armar([(100, "21"), (50, "10.5")], [(150, "5.2")]))
# Un flete inventado de 123456.78 pesos más IVA al 21 %
print(armar([("123456.78", "21")]))

WITH c AS (
  SELECT id, nombre, REPLACE(cuit, '-', '') AS cuit FROM crm_cuenta
)
SELECT c.id, c.nombre, c.cuit, e.codigo
FROM c LEFT JOIN erp_cliente e ON REPLACE(e.cuit, '-', '') = c.cuit
ORDER BY c.id;
